    [3] = {
      beijing = 1232,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      sentence = "LFG was becoming too much of a responsibility, so Victor had no time to run Souvenir. I looked up toward the blue light upon the TV tower.",
