    },
    [4] = {
      beijing = 1232,
      dialog = 3,
      music = "30_WarmSnow",
      renwu = "npc",
      sentence = "Now that we were in permanent night, the TV tower had a yellow light during the day, and a blue one at night. In these few days, people had already gotten used to marking the passage of time like this.",
